import numpy as np


def apply_convolution_valid(arr1 : np.ndarray , arr2 : np.ndarray) -> np.ndarray:
    a = np.asarray(arr1)
    k = np.asarray(arr2)

    if a.ndim == 1 and k.ndim == 1:
        return np.convolve(a, k, mode='valid')

    if a.ndim != k.ndim:
        raise ValueError("arr1 and arr2 must have the same number of dimensions")

    # Valid mode needs one input to cover the other in every dimension.
    if all(ks >= as_ for ks, as_ in zip(k.shape, a.shape)):
        a, k = k, a
    if any(ks > as_ for ks, as_ in zip(k.shape, a.shape)):
        raise ValueError("Kernel must not be larger than the input in any dimension")

    # Convolution flips the kernel; sliding windows then give the valid output.
    flipped = k[(slice(None, None, -1),) * k.ndim]
    windows = np.lib.stride_tricks.sliding_window_view(a, k.shape)
    return np.sum(windows * flipped, axis=tuple(range(-k.ndim, 0)))

