import nltk
from nltk.stem import PorterStemmer
from nltk.corpus import wordnet

def align_words_func(hypothesis, reference):
    """
    Align words between hypothesis and reference sentences.

    Args:
        hypothesis (list): List of words in the hypothesis sentence.
        reference (list): List of words in the reference sentence.

    Returns:
        tuple: A tuple containing the aligned matches, unmatched hypothesis, and unmatched reference.
    """
    stemmer = PorterStemmer()

    hyp_items = [(i, w) for i, w in enumerate(hypothesis)]
    ref_items = [(j, w) for j, w in enumerate(reference)]

    def exact_fn(h, r):
        return h.lower() == r.lower()

    def stem_fn(h, r):
        return stemmer.stem(h.lower()) == stemmer.stem(r.lower())

    def syn_fn(h, r):
        try:
            h_syns = set(wordnet.synsets(h.lower()))
            r_syns = set(wordnet.synsets(r.lower()))
        except LookupError:
            return False
        return bool(h_syns & r_syns)

    matches = []
    unmatched_hyp = list(hyp_items)
    unmatched_ref = list(ref_items)

    for match_fn in (exact_fn, stem_fn, syn_fn):
        next_hyp = []
        for hi, hw in unmatched_hyp:
            found = None
            for idx, (rj, rw) in enumerate(unmatched_ref):
                if match_fn(hw, rw):
                    found = idx
                    break
            if found is None:
                next_hyp.append((hi, hw))
            else:
                rj, _ = unmatched_ref.pop(found)
                matches.append((hi, rj))
        unmatched_hyp = next_hyp

    matches.sort()
    return matches, unmatched_hyp, unmatched_ref
