from scipy.ndimage import median_filter
import numpy as np 
def apply_median_filter(A: np.ndarray, size:int) -> np.ndarray:
    A = np.asarray(A)
    if A.ndim < 2:
        return median_filter(A, size=size)
    # Filter each sample independently: window size 1 along the batch axis (axis 0),
    # and `size` along all remaining axes. Other parameters use their defaults.
    footprint_size = (1,) + (size,) * (A.ndim - 1)
    return median_filter(A, size=footprint_size)

