from scipy.ndimage import minimum_filter
import numpy as np 
def apply_minimum_filter(A: np.ndarray, size: int) -> np.ndarray:
    A = np.asarray(A)
    if A.ndim == 0:
        return A.copy()
    if A.ndim == 1:
        return minimum_filter(A, size=size)
    # Keep the leading (batch) dimension and any extra leading (e.g. channel)
    # dimensions at size 1 so that filtering never mixes different images.
    # The last two dimensions are treated as spatial (H, W).
    footprint_size = (1,) * (A.ndim - 2) + (size, size)
    return minimum_filter(A, size=footprint_size)

