import numpy as np
from scipy.signal import hilbert

def compute_hilbert_transform(a: np.ndarray, b: np.ndarray, dtype=np.float64) -> np.ndarray:
    # compute_hilbert_transform should return the Hilbert transform of the
    # a and b arrays stacked vertically, with safe casting and the specified
    # dtype.
    # raise TypeError if needed
    if not isinstance(a, np.ndarray) or not isinstance(b, np.ndarray):
        raise TypeError("a and b must be numpy.ndarray instances")

    for arr in (a, b):
        if arr.dtype.kind not in "biufc":
            raise TypeError(
                f"unsupported array dtype {arr.dtype}; expected a real or complex numeric dtype"
            )

    try:
        target = np.dtype(dtype)
    except TypeError as exc:
        raise TypeError(f"invalid dtype specification: {dtype!r}") from exc

    if target.kind not in "fc":
        raise TypeError(f"dtype must be a floating or complex type, got {target}")

    stacked = np.vstack((a, b))
    analytic = hilbert(stacked, axis=-1)

    if target.kind == "c":
        result = analytic
    else:
        # The Hilbert transform is the imaginary part of the analytic signal.
        result = np.imag(analytic)

    if not np.can_cast(result.dtype, target, casting="safe"):
        raise TypeError(
            f"cannot safely cast result of dtype {result.dtype} to {target}"
        )

    return result.astype(target, casting="safe")

