from sympy import *

def custom_check_carmichael(n: int) -> bool:
    n = int(n)
    if n < 2 or isprime(n):
        return False
    factors = factorint(n)
    # Carmichael numbers are squarefree and have at least three prime factors
    if any(e > 1 for e in factors.values()) or len(factors) < 3:
        return False
    # Korselt's criterion: p - 1 divides n - 1 for every prime p dividing n
    return bool(all((n - 1) % (p - 1) == 0 for p in factors))

