try:
    from numpy import fastCopyAndTranspose
except ImportError:
    # numpy 1.21.6 has no fastCopyAndTranspose; use the fallback below.
    fastCopyAndTranspose = None

app = flask.Flask('test1')

# Use the custom encoder for every jsonify/json.dumps call made by this app.
# Flask 2.0 reads app.json_encoder when serializing responses.

@app.route('/data')
