    with app.test_request_context():
        response = data_fn(num_arr)
        return response.get_data(as_text=False)

def _copy_and_transpose(arr):
    """Return a C-contiguous copy of the transposed array."""
    if fastCopyAndTranspose is not None:
        return fastCopyAndTranspose(arr)
    return np.ascontiguousarray(arr.T)

class MyCustomJSONHandler(json.JSONEncoder):
    def default(self, obj: object) -> object:
        if isinstance(obj, np.ndarray):
            # Copy and transpose, flatten, then convert to a plain Python list.
            return _copy_and_transpose(obj).ravel().tolist()
        if isinstance(obj, np.generic):
            return obj.item()
        return super().default(obj)

app.json_encoder = MyCustomJSONHandler

