from sympy import Matrix, symbols, Array
import sympy

def custom_array_to_matrix(array: sympy.Array) -> sympy.Matrix:
    from sympy.tensor.array.ndim_array import NDimArray

    if not isinstance(array, NDimArray):
        array = Array(array)

    rank = array.rank()
    if rank == 1:
        return Matrix(array.tolist())  # column vector
    if rank == 2:
        return Matrix(array.tolist())
    raise ValueError(f"Cannot convert rank-{rank} array to a Matrix; expected rank 1 or 2.")

