import falcon.routing


class CustomRouter:
    def __init__(self):
        self.routes = {}


def solution() -> None:

    def add_route(self, uri_template, resource, **kwargs):
        # falcon.routing.map_http_methods(resource, suffix=None) has no 'fallback'
        # parameter in falcon 2.0.0, so the 'fallback' value is forwarded as 'suffix'.
        suffix = kwargs.pop("fallback", None)
        method_map = falcon.routing.map_http_methods(resource, suffix=suffix)
        self.routes[uri_template] = (resource, method_map)
        return method_map

    CustomRouter.add_route = add_route

