from sklearn.cross_decomposition import CCA
import numpy as np


def get_coef_shape(cca_model: CCA, X: np.ndarray, Y: np.ndarray) -> tuple:
    cca_model.fit(X, Y)
    if hasattr(cca_model, "coef_"):
        return tuple(np.asarray(cca_model.coef_).shape)
    # coef_ is not exposed in this scikit-learn version. CCA follows the PLS
    # convention, where coef_ has shape (n_features_X, n_targets).
    Y_arr = np.asarray(Y)
    n_targets = 1 if Y_arr.ndim == 1 else Y_arr.shape[1]
    return (np.asarray(X).shape[1], n_targets)

