import numpy as np
def get_expected_value(df: pd.DataFrame) -> pd.Series:
    # Empty frame: nothing to set, return an empty Series.
    if df.shape[0] == 0 or df.shape[1] == 0:
        return pd.Series(dtype=object)

    # Set the first row in place from the last row (column-wise, dtype-preserving).
    df.iloc[0, :] = df.iloc[-1, :].values

    # Return the first row as an independent Series, so later changes to df do not affect it.
    return df.iloc[0, :].copy()

