import numpy as np

def compute_matrix_exponential(A: np.ndarray) -> np.ndarray:
    A = np.asarray(A)
    if A.ndim < 2 or A.shape[-1] != A.shape[-2]:
        raise ValueError("Input must have shape (..., n, n) with square matrices.")

    if A.ndim == 2:
        return linalg.expm(A)

    n = A.shape[-1]
    batch_shape = A.shape[:-2]
    flat = A.reshape((-1, n, n))

    if flat.shape[0] == 0:
        out_dtype = np.result_type(A.dtype, np.float64)
        return np.zeros(A.shape, dtype=out_dtype)

    results = [linalg.expm(flat[i]) for i in range(flat.shape[0])]
    out = np.stack(results, axis=0)
    return out.reshape(batch_shape + (n, n))

