def custom_use(expr: sympy.Expr) -> int:
    def _evaluate(e):
        if not isinstance(e, sympy.Basic):
            return e
        if isinstance(e, sympy.UnevaluatedExpr):
            return _evaluate(e.args[0])
        if not e.args:
