import numpy as np


def custom_iqr(data: np.ndarray) -> float:
    arr = np.asarray(data, dtype=float).ravel()
    arr = arr[~np.isnan(arr)]
    if arr.size == 0:
        return float("nan")
    arr = np.sort(arr)

    def _quantile(sorted_arr: np.ndarray, q: float) -> float:
        n = sorted_arr.size
        pos = q * (n - 1)
        lo = int(np.floor(pos))
        hi = min(lo + 1, n - 1)
        frac = pos - lo
        return float(sorted_arr[lo] + (sorted_arr[hi] - sorted_arr[lo]) * frac)

    return _quantile(arr, 0.75) - _quantile(arr, 0.25)

