import pandas as pd
import numpy as np


def get_expected_value(df: pd.DataFrame) -> pd.Series:
    # Work on a copy so the caller's DataFrame is left unchanged.
    result = df.copy()
    if result.empty or result.shape[1] == 0:
        return pd.Series(dtype=float)

    # Cast the first column to float so assigning NaN never raises a dtype error.
    first_col = result.columns[0]
    result[first_col] = result[first_col].astype(float)

    # In-place positional assignment with iloc on the copy.
    result.iloc[0, 0] = np.nan

    return result.iloc[:, 0].copy()

