import numpy as np

def compute_determinant(A: np.ndarray) -> np.ndarray:
    A = np.asarray(A)
    if A.ndim < 2 or A.shape[-1] != A.shape[-2]:
        raise ValueError("Input must have shape (batch, n, n) with square matrices.")
    if A.ndim == 2:
        return np.asarray(det(A))
    batch_shape = A.shape[:-2]
    flat = A.reshape((-1,) + A.shape[-2:])
    dets = np.empty(flat.shape[0], dtype=np.result_type(flat.dtype, np.float64))
    for i in range(flat.shape[0]):
        dets[i] = det(flat[i])
    return dets.reshape(batch_shape)

