import numpy as np
from PIL import Image, ImageChops


def imaging(img1: Image, img2: Image) -> Image:
    # ImageChops operations require matching modes and sizes.
    # Convert unsupported modes (e.g. P, RGBA) to RGB first.
    if img1.mode not in ("RGB", "L"):
        img1 = img1.convert("RGB")
    if img2.mode != img1.mode:
        img2 = img2.convert(img1.mode)
    if img2.size != img1.size:
        img2 = img2.resize(img1.size)

    return ImageChops.soft_light(img1, img2)

