import networkx as nx


def naive_modularity_communities(G: nx.Graph) -> list:
    # networkx 2.4 does not provide naive_greedy_modularity_communities,
    # so this implements the Clauset-Newman-Moore naive greedy algorithm directly.
    nodes = list(G.nodes())
    n = len(nodes)
    if n == 0:
        return []
    index = {v: i for i, v in enumerate(nodes)}

    m = 0.0
    internal = [0.0] * n  # total weight of edges inside each community
    degree = [0.0] * n    # total degree of each community
    adj = [dict() for _ in range(n)]  # weight of edges between communities
    for u, v, d in G.edges(data=True):
        w = float(d.get("weight", 1))
        i, j = index[u], index[v]
        m += w
        if i == j:
            internal[i] += w
            degree[i] += 2 * w
        else:
            degree[i] += w
            degree[j] += w
            adj[i][j] = adj[i].get(j, 0.0) + w
            adj[j][i] = adj[j].get(i, 0.0) + w

    if m == 0:
        return [frozenset([v]) for v in nodes]

    members = {i: {i} for i in range(n)}

    def modularity():
        return sum(internal[c] / m - (degree[c] / (2 * m)) ** 2 for c in members)

    def snapshot():
        return [frozenset(nodes[x] for x in members[c]) for c in sorted(members)]

    best_q = modularity()
    best = snapshot()

    while len(members) > 1:
        # Find the adjacent pair of communities with the largest modularity gain.
        best_pair = None
        best_gain = None
        for i in sorted(members):
            for j, w in adj[i].items():
                if j <= i:
                    continue
                gain = w / m - degree[i] * degree[j] / (2 * m * m)
                if best_gain is None or gain > best_gain:
                    best_gain = gain
                    best_pair = (i, j)
        if best_pair is None:
            # No communities are connected by edges; nothing more to merge.
            break

        # Merge community j into community i.
        i, j = best_pair
        internal[i] += internal[j] + adj[i][j]
        degree[i] += degree[j]
        members[i] |= members.pop(j)
        for c, w in adj[j].items():
            if c == i:
                continue
            adj[i][c] = adj[i].get(c, 0.0) + w
            adj[c][i] = adj[c].get(i, 0.0) + w
            del adj[c][j]
        adj[i].pop(j, None)
        adj[j] = {}

        q = modularity()
        if q > best_q + 1e-12:
            best_q = q
            best = snapshot()

    return best

