from scipy import linalg
import numpy as np

def compute_matrix_exponential(A: np.ndarray) -> np.ndarray:
    A = np.asarray(A)
    if A.ndim < 2 or A.shape[-1] != A.shape[-2]:
        raise ValueError("Input must be a (..., M, M) array of square matrices.")

    if A.ndim == 2:
        return linalg.expm(A)

    batch_shape = A.shape[:-2]
    matrix_shape = A.shape[-2:]
    batch_size = int(np.prod(batch_shape))

    flat = A.reshape((batch_size,) + matrix_shape)
    out_dtype = np.result_type(flat.dtype, np.float64)
    out = np.empty(flat.shape, dtype=out_dtype)

    for i in range(batch_size):
        out[i] = linalg.expm(flat[i])

    return out.reshape(A.shape)

