from scipy.ndimage import gaussian_filter
import numpy as np 
def apply_gaussian_filter(A: np.ndarray, sigma: float) -> np.ndarray:
    A = np.asarray(A)
    if A.ndim == 0:
        return gaussian_filter(A, sigma)
    # Axis 0 is the batch dimension: sigma=0 disables filtering along it,
    # so each image in the batch is filtered independently.
    sigmas = (0,) + (sigma,) * (A.ndim - 1)
    return gaussian_filter(A, sigma=sigmas)

