class MyCustomJSONHandler(json.JSONEncoder):
    def default(self, obj: object) -> object:
        if isinstance(obj, np.ndarray):
            flat = obj.ravel()
            if np.issubdtype(flat.dtype, np.floating):
                is_nan = np.isnan(flat)
                # Unique non-NaN values, sorted
                uniq = np.unique(flat[~is_nan]).tolist()
                # Each NaN is treated as a distinct value
                uniq.extend([float('nan')] * int(is_nan.sum()))
                return uniq
            return np.unique(flat).tolist()
        return super().default(obj)

