import sympy


def custom_use(expr: sympy.Expr) -> int:
    def _evaluate(node):
        # Atoms (numbers, symbols) have no arguments, so they are already fully evaluated.
        if not node.args:
            return node
        # Evaluate every child subexpression first (post-order traversal),
        # then rebuild this node from the evaluated children so it is evaluated too.
        evaluated_args = [_evaluate(arg) for arg in node.args]
        return node.func(*evaluated_args)

    result = _evaluate(sympy.sympify(expr))
    return int(sympy.sympify(result))

