import librosa
import numpy as np

def compute_shear(E: np.ndarray, factor: int, axis: int) -> np.ndarray:
    # librosa.util.shear is not available in librosa 0.7.0, so shear is implemented with numpy.
    if E.ndim != 2:
        raise ValueError("compute_shear expects a 2-D array")
    if axis < 0:
        axis += E.ndim
    if axis not in (0, 1):
        raise ValueError("axis must be 0 or 1 (or -1/-2)")

    n_rows, n_cols = E.shape
    if E.size == 0:
        return E.copy()

    if axis == 1:
        # Each row i is circularly shifted by factor * i.
        rows = np.arange(n_rows)[:, None]
        cols = (np.arange(n_cols)[None, :] + factor * np.arange(n_rows)[:, None]) % n_cols
    else:
        # Each column j is circularly shifted by factor * j.
        rows = (np.arange(n_rows)[:, None] + factor * np.arange(n_cols)[None, :]) % n_rows
        cols = np.arange(n_cols)[None, :]

    return E[rows, cols]

