import scipy.signal.windows as windows
import numpy as np

def compute_lanczos_window(window_size:int)->np.ndarray:
    M = int(window_size)
    if M <= 0:
        return np.zeros(0)
    if M == 1:
        return np.ones(1)

    lanczos_fn = getattr(windows, "lanczos", None)
    if lanczos_fn is not None:
        # Available in SciPy >= 1.10.1; default sym=True.
        return np.asarray(lanczos_fn(M), dtype=float)

    # Fallback for SciPy 1.9.2: symmetric Lanczos window, identical to
    # scipy.signal.windows.lanczos(M, sym=True).
    return np.sinc(np.linspace(-1.0, 1.0, M))

