        # falcon.routing.map_http_methods(resource, suffix=None) in falcon 2.0.0
        # does not accept a 'fallback' keyword, so the fallback value is passed
        # through as the 'suffix' argument instead.
        if 'fallback' in kwargs:
            method_map = falcon.routing.map_http_methods(
                resource, suffix=kwargs['fallback']
            )
        else:
            method_map = falcon.routing.map_http_methods(resource)

        self.routes[uri_template] = (resource, method_map)
        return method_map

